<?php
require_once __DIR__.'/bootstrap.php';
require_once __DIR__.'/services/AttainmentPolicyService.php';
$db=(new DBCredentials())->getConnection();
$reg=(int)($_POST['reg_id']??$_GET['reg_id']??0);$type=(string)($_POST['subject_type']??$_GET['subject_type']??'all');$subject=(int)($_POST['sub_id']??$_GET['sub_id']??0);
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$message=$error='';
$regs=$db->query('SELECT id,regulation,prog_id FROM regulations ORDER BY id')->fetch_all(MYSQLI_ASSOC);
$types=array_column($db->query('SELECT DISTINCT sub_type FROM subjects ORDER BY sub_type')->fetch_all(MYSQLI_ASSOC),'sub_type');
$load=static function()use($db,$reg,$type,$subject){if($subject){$stmt=$db->prepare('SELECT config_json,version FROM subject_attainment_overrides WHERE subject_id=?');$stmt->bind_param('i',$subject);}else{$stmt=$db->prepare('SELECT config_json,version FROM attainment_policies WHERE regulation_id=? AND subject_type=?');$stmt->bind_param('is',$reg,$type);}$stmt->execute();return $stmt->get_result()->fetch_assoc()?:['config_json'=>'{}','version'=>0];};
$offerings=[];if($reg){$stmt=$db->prepare('SELECT s.id,s.subcode,s.sub_fullname,c.classname FROM subjects s JOIN classes c ON c.id=s.class_id WHERE c.reg_id=? ORDER BY c.id DESC,s.subcode');$stmt->bind_param('i',$reg);$stmt->execute();$offerings=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);}
$current=$load();$config=json_decode($current['config_json'],true);
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{$config=json_decode($_POST['advanced']?:'{}',true,512,JSON_THROW_ON_ERROR);if(!is_array($config)||($config&&array_is_list($config))){throw new InvalidArgumentException('Advanced rules must be a JSON object.');}
        foreach(['net_max','gross_max','internal_max','co_target_percentage','attainment_level_1_threshold','attainment_level_2_threshold','attainment_level_3_threshold'] as $key){$value=trim((string)($_POST[$key]??''));if($value===''){unset($config[$key]);}else{$config[$key]=\College\MarksNormalizer::number($value,$key);}}
        $config['grade_strategy']=$_POST['grade_strategy']??'NONE';
        (new \Services\AttainmentPolicyService())->save($reg,$type,$config,(int)$_POST['version'],$subject?:null);$message='Profile saved. Existing marks remain recorded with their original evidence.';$current=$load();
    }catch(Throwable $ex){$error=$ex->getMessage();}
}
$page_title='Attainment profiles';require __DIR__.'/superadminheader.php';
$advanced=array_diff_key($config,array_flip(['net_max','gross_max','internal_max','grade_strategy','co_target_percentage','attainment_level_1_threshold','attainment_level_2_threshold','attainment_level_3_threshold']));
?>
<div class="container my-4"><h4>Attainment profiles</h4><p>Set rules for an exact regulation and subject type. A subject override takes priority. Blank fields inherit the existing curriculum or profile; missing curriculum links are optional.</p>
<?php if($error):?><div class="alert alert-danger"><?= $e($error) ?></div><?php endif ?><?php if($message):?><div class="alert alert-success"><?= $e($message) ?></div><?php endif ?>
<form method="get" class="row g-2 mb-4"><div class="col-md-4"><label>Regulation</label><select class="form-select" name="reg_id" required><option value="">Choose regulation</option><?php foreach($regs as $r):?><option value="<?= (int)$r['id'] ?>" <?= $reg===$r['id']?'selected':($reg===(int)$r['id']?'selected':'') ?>><?= $e($r['regulation']) ?> — program <?= (int)$r['prog_id'] ?> (ID <?= (int)$r['id'] ?>)</option><?php endforeach ?></select></div><div class="col-md-3"><label>Subject type</label><select name="subject_type" class="form-select"><?php foreach(array_merge(['all'],$types) as $t):?><option <?= $type===$t?'selected':'' ?>><?= $e($t) ?></option><?php endforeach ?></select></div><div class="col-md-3"><label>Course override (optional)</label><select class="form-select" name="sub_id"><option value="0">Use regulation/type profile</option><?php foreach($offerings as $offering):?><option value="<?= (int)$offering['id'] ?>" <?= $subject===(int)$offering['id']?'selected':'' ?>><?= $e($offering['subcode'].' — '.$offering['sub_fullname'].' — '.$offering['classname']) ?></option><?php endforeach ?></select></div><div class="col-md-2 align-self-end"><button class="btn btn-secondary">Load</button></div></form>
<?php if($reg):?><form method="post"><input type="hidden" name="reg_id" value="<?= $reg ?>"><input type="hidden" name="subject_type" value="<?= $e($type) ?>"><input type="hidden" name="sub_id" value="<?= $subject ?>"><input type="hidden" name="version" value="<?= (int)$current['version'] ?>"><div class="row g-3">
<?php foreach(['net_max'=>'Final external maximum','gross_max'=>'Gross paper maximum','internal_max'=>'Internal maximum','co_target_percentage'=>'Student CO target (%)','attainment_level_1_threshold'=>'Level 1 cohort threshold (%)','attainment_level_2_threshold'=>'Level 2 cohort threshold (%)','attainment_level_3_threshold'=>'Level 3 cohort threshold (%)'] as $key=>$label):?><div class="col-md-4"><label for="<?= $key ?>"><?= $label ?></label><input class="form-control" id="<?= $key ?>" name="<?= $key ?>" type="number" step="any" min="0" value="<?= $e($config[$key]??'') ?>"></div><?php endforeach ?>
<div class="col-md-4"><label>Grade-only estimates</label><select class="form-select" name="grade_strategy"><?php foreach(['NONE'=>'Disabled','LOWER_BOUND'=>'Use lower limit','MIDPOINT'=>'Use midpoint','UPPER_BOUND'=>'Use upper limit'] as $key=>$label):?><option value="<?= $key ?>" <?= ($config['grade_strategy']??'NONE')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div></div>
<details class="my-3"><summary>Advanced: grade bands and choice rules</summary><p class="small mt-2">Use grade_bands with grade, min_percent, max_percent and points. Use choice_groups with options (lists of question labels) and select (number of options). All conversion remains labelled as an estimate.</p><textarea name="advanced" class="form-control font-monospace" rows="12"><?= $e(json_encode((object)$advanced,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)) ?></textarea></details><button class="btn btn-primary">Save profile</button></form><?php endif ?></div>
<?php require __DIR__.'/superadminfooter.php'; ?>
